insert into public.career_categories (id, name, description, interests, sort_order) values
  ('technology', 'Technology & Data', 'Building software, working with computers and networks, and using data to answer questions.', array['tech', 'logic']::text[], 1),
  ('health', 'Health & Life Sciences', 'Caring for people’s health and studying living things, medicines and disease.', array['life', 'people', 'logic']::text[], 2),
  ('engineering', 'Engineering & the Built Environment', 'Designing, building and maintaining roads, buildings, machines, power and property.', array['build', 'logic', 'practical']::text[], 3),
  ('business', 'Business, Finance & Enterprise', 'Managing money, running organisations, starting businesses and understanding the economy.', array['organise', 'logic', 'people']::text[], 4),
  ('law-society', 'Law, Government & Society', 'Understanding laws, rights, government and how society works, and helping it work better.', array['people', 'communicate', 'organise']::text[], 5),
  ('media', 'Media, Writing & Communication', 'Telling stories, sharing information and creating content for newspapers, radio, TV and online.', array['communicate', 'creative', 'tech']::text[], 6),
  ('education-care', 'Education & Social Care', 'Teaching, guiding and supporting children, families and communities.', array['people', 'communicate']::text[], 7),
  ('agriculture', 'Agriculture, Food & Environment', 'Growing food, caring for animals and land, processing food safely and protecting the environment.', array['nature', 'life', 'practical']::text[], 8),
  ('creative', 'Creative Arts & Design', 'Art, fashion, film, performance and design that people can see, wear and experience.', array['creative', 'build', 'communicate']::text[], 9),
  ('technical', 'Technical & Vocational Trades', 'Skilled hands-on work such as electrical installation, laboratory work and other practical trades.', array['practical', 'build', 'tech']::text[], 10)
insert into public.subject_pathways (id, name, summary, overview, subjects, skills, interests, limitations, alternatives, sort_order) values
  ('science', 'Science', 'For students curious about how nature, the human body and machines work.', 'The Science pathway usually focuses on Mathematics and the natural sciences. It is the common route into health, engineering, computing and many agriculture and laboratory courses, because those courses often ask for Physics, Chemistry and Biology.', array['Mathematics', 'English Language', 'Physics', 'Chemistry', 'Biology', 'Further Mathematics', 'Agricultural Science', 'Digital Technology (ICT)', 'Technical Drawing', 'Geography']::text[], array['Problem solving', 'Careful observation', 'Working with numbers', 'Doing experiments safely']::text[], array['logic', 'life', 'tech', 'build', 'nature']::text[], 'Science courses often need strong results in three or more science subjects plus Mathematics. If you drop Physics or Chemistry early, some health and engineering courses may become harder to enter.', 'Science students can also study business, social science and some arts courses if they add the right subjects (for example Economics or Literature). Polytechnic ND programmes and technical colleges offer practical science routes.', 1),
  ('arts', 'Arts & Humanities', 'For students who enjoy language, literature, history, beliefs, culture and creative expression.', 'The Arts pathway builds reading, writing and thinking skills. It is a common route into law, languages, media, theatre, history, religious studies and teaching.', array['English Language', 'Mathematics', 'Literature in English', 'Government', 'History', 'Christian Religious Studies / Islamic Studies', 'Nigerian languages (e.g. Yoruba, Igbo, Hausa)', 'French', 'Fine Arts', 'Music', 'Civic Education']::text[], array['Clear writing', 'Public speaking', 'Critical reading', 'Understanding people and culture']::text[], array['communicate', 'people', 'creative']::text[], 'Most science, health and engineering degrees are not open to students without the required science subjects. Many institutions still require a credit in Mathematics, even for arts courses.', 'Arts students can move into social sciences, education, media and creative industries. Some business courses accept arts students who also have Economics or Mathematics credits.', 2),
  ('commercial', 'Commercial & Business Studies', 'For students interested in money, trade, business and how organisations are run.', 'The Commercial pathway focuses on Economics, accounting, commerce and business. It leads naturally into accounting, banking, business administration, marketing and economics.', array['English Language', 'Mathematics', 'Economics', 'Financial Accounting', 'Commerce', 'Office Practice', 'Marketing', 'Government', 'Geography', 'Data Processing']::text[], array['Working with numbers', 'Organising information', 'Negotiation', 'Understanding markets']::text[], array['organise', 'logic', 'people']::text[], 'Commercial subjects alone usually do not qualify you for science, health or engineering courses. Strong Mathematics is important for accounting, banking and economics.', 'Commercial students can study many social science courses, some technology-related business courses, and entrepreneurship programmes. Professional bodies offer routes into accounting outside university.', 3),
  ('social-sciences', 'Social Sciences', 'For students who want to understand people, communities, government and the economy.', 'Social science courses study how people behave and how societies are organised. In many schools these subjects sit inside the Arts or Commercial classes rather than being a separate class. Courses include Economics, Political Science, Psychology, Sociology and Geography.', array['English Language', 'Mathematics', 'Economics', 'Government', 'Geography', 'Civic Education', 'History', 'Biology']::text[], array['Research', 'Analysing information', 'Debate and discussion', 'Understanding different viewpoints']::text[], array['people', 'communicate', 'logic', 'organise']::text[], 'Subject requirements vary a lot between social science courses. For example, Economics often needs Mathematics, while Psychology may ask for Biology at some institutions.', 'Students from Science, Arts and Commercial classes can all reach social science courses with the right subject combination.', 4),
  ('technical', 'Technical & Vocational Studies', 'For students who like practical, hands-on skills and making or fixing things.', 'Technical and vocational studies teach practical trades and technologies, such as electrical installation, building, automobile work, catering, fashion and computing. They are offered at technical colleges and in many secondary schools, and they can lead to polytechnic programmes, apprenticeships or self-employment.', array['English Language', 'Mathematics', 'Basic Technology', 'Technical Drawing', 'Physics', 'Electrical Installation', 'Building Construction', 'Garment Making', 'Catering Craft', 'Digital Technology (ICT)']::text[], array['Working safely with tools', 'Following technical drawings', 'Fault finding', 'Practical creativity']::text[], array['practical', 'build', 'tech', 'creative']::text[], 'Some university degrees expect academic science subjects in addition to technical subjects. Check whether your trade subjects are accepted for the course you want.', 'Technical students can continue to polytechnic ND and HND programmes, enter direct apprenticeships, or move to university through recognised routes. Trade certificates are offered by bodies such as NABTEB.', 5)
insert into public.courses (id, name, category_id, summary, description, what_you_learn, helpful_subjects, workplaces, skills, further_study, interests, institution_types, typical_duration, published) values
  ('computer-science', 'Computer Science', 'technology', 'How computers work and how to make them solve problems with software.', 'Computer Science teaches you to think like a problem solver and to write programs. You learn how software, data and networks work, and how to design systems that people can rely on.', array['Programming in several languages', 'Algorithms and data structures', 'Databases', 'Computer networks', 'Software design', 'Artificial intelligence basics']::text[], array['Mathematics', 'English Language', 'Physics', 'Further Mathematics', 'Digital Technology (ICT)']::text[], array['Technology companies and start-ups', 'Banks and fintech companies', 'Telecommunications companies', 'Government agencies', 'Schools and universities']::text[], array['Logical thinking', 'Coding', 'Debugging', 'Teamwork on projects']::text[], array['M.Sc. in Computer Science or related fields', 'Industry certifications (cloud, networking, security)', 'Registration with the Computer Professionals Registration Council of Nigeria (CPN)']::text[], array['tech', 'logic']::text[], array['university', 'polytechnic']::text[], 'About 4 years for a degree; ND/HND routes exist at polytechnics.', true),
  ('software-engineering', 'Software Engineering', 'technology', 'Planning, building and testing reliable software products in teams.', 'Software Engineering focuses on building software the way engineers build bridges: carefully planned, tested and maintained. It is close to Computer Science but spends more time on teamwork, project management and quality.', array['Programming and software design', 'Requirements and user needs', 'Testing and quality assurance', 'Project management', 'Mobile and web development']::text[], array['Mathematics', 'English Language', 'Physics', 'Digital Technology (ICT)']::text[], array['Software companies', 'Fintech and e-commerce companies', 'Consulting firms', 'Remote work for international teams']::text[], array['Coding', 'Working in teams', 'Planning projects', 'Communicating with users']::text[], array['Postgraduate study in software or computing', 'Professional certifications', 'CPN registration']::text[], array['tech', 'logic', 'build']::text[], array['university']::text[], 'About 4 years for a degree.', true),
  ('statistics', 'Statistics', 'technology', 'Collecting and analysing data to find patterns and make good decisions.', 'Statistics is the science of learning from data. Statisticians help governments, hospitals, businesses and researchers understand numbers and make decisions based on evidence.', array['Probability', 'Data collection and surveys', 'Statistical computing', 'Data visualisation', 'Research methods']::text[], array['Mathematics', 'Further Mathematics', 'English Language', 'Economics', 'Physics']::text[], array['National and state statistics offices', 'Banks and insurance companies', 'Research organisations', 'Health programmes and NGOs', 'Technology companies']::text[], array['Working with numbers', 'Using spreadsheets and statistical software', 'Explaining findings clearly']::text[], array['M.Sc. in Statistics or Data Science', 'Actuarial science examinations']::text[], array['logic', 'tech', 'organise']::text[], array['university', 'polytechnic']::text[], 'About 4 years for a degree; ND/HND routes exist at polytechnics.', true),
  ('medicine', 'Medicine and Surgery', 'health', 'Training to diagnose and treat illness and to care for patients as a doctor.', 'Medicine and Surgery (MBBS) trains you to become a medical doctor. It is a long, demanding course that combines science with clinical training in hospitals. After graduating, doctors complete a supervised internship before full registration.', array['Human anatomy and physiology', 'Biochemistry', 'Pharmacology', 'Diagnosing and treating disease', 'Clinical skills in hospital wards', 'Community health']::text[], array['Biology', 'Chemistry', 'Physics', 'Mathematics', 'English Language']::text[], array['Public and private hospitals', 'Primary health care centres', 'Research institutes', 'NGOs and international health programmes', 'Armed forces medical services']::text[], array['Careful observation', 'Communication with patients', 'Working under pressure', 'Lifelong learning']::text[], array['Housemanship (internship) and full registration with the Medical and Dental Council of Nigeria (MDCN)', 'Residency training to specialise (e.g. paediatrics, surgery)', 'Master’s in Public Health']::text[], array['life', 'people', 'logic']::text[], array['university']::text[], 'Usually about 6 years, followed by an internship.', true),
  ('nursing', 'Nursing Science', 'health', 'Caring for patients, promoting health and working alongside doctors and other health workers.', 'Nursing Science prepares you to care for people of all ages in hospitals and communities. Nurses give treatment, monitor patients, educate families and often lead health teams.', array['Anatomy and physiology', 'Nursing care and procedures', 'Maternal and child health', 'Mental health nursing', 'Community health', 'Clinical placements']::text[], array['Biology', 'Chemistry', 'Physics', 'Mathematics', 'English Language']::text[], array['Hospitals and clinics', 'Primary health care centres', 'Schools and companies', 'NGOs and health programmes']::text[], array['Compassion and patience', 'Attention to detail', 'Teamwork', 'Calm under pressure']::text[], array['Registration with the Nursing and Midwifery Council of Nigeria (NMCN)', 'Specialist nursing and midwifery programmes', 'Postgraduate nursing degrees']::text[], array['life', 'people', 'practical']::text[], array['university', 'other']::text[], 'About 5 years for a degree. Some schools of nursing offer other recognised routes.', true),
  ('pharmacy', 'Pharmacy', 'health', 'The science of medicines: how they are made, how they work and how to use them safely.', 'Pharmacy trains you to understand medicines from the laboratory to the patient. Pharmacists make sure people receive the right medicine, at the right dose, and understand how to use it.', array['Pharmaceutical chemistry', 'Pharmacology', 'Making and testing medicines', 'Clinical pharmacy', 'Drug safety and regulation']::text[], array['Chemistry', 'Biology', 'Physics', 'Mathematics', 'English Language']::text[], array['Community pharmacies', 'Hospitals', 'Pharmaceutical manufacturing companies', 'Drug regulation agencies', 'Research']::text[], array['Accuracy', 'Scientific thinking', 'Advising people clearly', 'Ethics and responsibility']::text[], array['Internship and registration with the Pharmacy Council of Nigeria (PCN)', 'Postgraduate study in pharmacology or clinical pharmacy']::text[], array['life', 'logic', 'people']::text[], array['university']::text[], 'Usually about 5–6 years (B.Pharm or Pharm.D).', true),
  ('medical-lab-science', 'Medical Laboratory Science', 'health', 'Testing blood, tissue and other samples to help diagnose and monitor disease.', 'Medical Laboratory Science trains you to run the tests doctors rely on. Medical laboratory scientists work behind the scenes, but their results guide many treatment decisions.', array['Haematology (blood science)', 'Medical microbiology', 'Clinical chemistry', 'Histopathology', 'Laboratory safety and quality control']::text[], array['Biology', 'Chemistry', 'Physics', 'Mathematics', 'English Language']::text[], array['Hospital laboratories', 'Diagnostic centres', 'Public health laboratories', 'Research institutes', 'Blood banks']::text[], array['Precision', 'Using laboratory equipment', 'Following procedures', 'Record keeping']::text[], array['Internship and registration with the Medical Laboratory Science Council of Nigeria (MLSCN)', 'Specialist and postgraduate qualifications']::text[], array['life', 'practical', 'logic']::text[], array['university']::text[], 'About 5 years for a degree.', true),
  ('microbiology', 'Microbiology', 'health', 'Studying tiny living things such as bacteria, viruses and fungi, and how they affect us.', 'Microbiology looks at microorganisms that cause disease, spoil food or help make products like bread, yoghurt and medicines. It connects health, food and the environment.', array['Bacteriology and virology', 'Food and industrial microbiology', 'Genetics', 'Laboratory techniques', 'Environmental microbiology']::text[], array['Biology', 'Chemistry', 'Physics', 'Mathematics', 'English Language']::text[], array['Food and drink companies', 'Pharmaceutical companies', 'Research institutes', 'Public health agencies', 'Water treatment']::text[], array['Careful experiments', 'Recording results', 'Scientific writing']::text[], array['M.Sc. or PhD in Microbiology', 'Quality-control and food-safety certifications']::text[], array['life', 'logic', 'nature']::text[], array['university', 'polytechnic']::text[], 'About 4 years for a degree.', true),
  ('civil-engineering', 'Civil Engineering', 'engineering', 'Designing and building roads, bridges, buildings, water systems and drainage.', 'Civil engineers plan and build the structures that communities depend on every day. The course mixes mathematics and science with design projects and site experience.', array['Engineering mathematics', 'Structural analysis and design', 'Soil mechanics', 'Water and environmental engineering', 'Surveying', 'Construction management']::text[], array['Mathematics', 'Physics', 'Chemistry', 'Further Mathematics', 'Technical Drawing', 'English Language']::text[], array['Construction companies', 'Engineering consultancies', 'Ministries of Works', 'Water and transport agencies', 'Oil and gas companies']::text[], array['Problem solving', 'Technical drawing and design software', 'Teamwork on site', 'Safety awareness']::text[], array['Registration with the Council for the Regulation of Engineering in Nigeria (COREN)', 'Master’s in structural, water or transport engineering']::text[], array['build', 'logic', 'practical']::text[], array['university', 'polytechnic']::text[], 'About 5 years for a degree; ND/HND routes exist at polytechnics.', true),
  ('electrical-engineering', 'Electrical/Electronic Engineering', 'engineering', 'Power, electronics and communication systems — from the national grid to mobile phones.', 'Electrical and Electronic Engineering covers how electricity is generated, delivered and used, and how electronic devices and communication systems are designed.', array['Circuit theory', 'Power systems', 'Electronics', 'Telecommunications', 'Control systems', 'Renewable energy']::text[], array['Mathematics', 'Physics', 'Chemistry', 'Further Mathematics', 'English Language']::text[], array['Power generation and distribution companies', 'Telecommunications companies', 'Manufacturing', 'Solar and renewable energy firms', 'Oil and gas']::text[], array['Mathematical thinking', 'Fault finding', 'Using test equipment', 'Safety awareness']::text[], array['COREN registration', 'Postgraduate study in power, electronics or telecoms']::text[], array['build', 'logic', 'tech']::text[], array['university', 'polytechnic']::text[], 'About 5 years for a degree; ND/HND routes exist at polytechnics.', true),
  ('mechanical-engineering', 'Mechanical Engineering', 'engineering', 'Designing machines, engines, vehicles and production systems.', 'Mechanical Engineering is about anything that moves — from car engines and generators to factory machines and air-conditioning systems.', array['Mechanics and thermodynamics', 'Machine design', 'Manufacturing processes', 'Fluid mechanics', 'Computer-aided design (CAD)']::text[], array['Mathematics', 'Physics', 'Chemistry', 'Further Mathematics', 'Technical Drawing', 'English Language']::text[], array['Manufacturing companies', 'Automobile industry', 'Oil and gas', 'Power plants', 'Maintenance companies']::text[], array['Problem solving', 'Hands-on building', 'Design software', 'Teamwork']::text[], array['COREN registration', 'Postgraduate study in mechanical, energy or production engineering']::text[], array['build', 'logic', 'practical']::text[], array['university', 'polytechnic']::text[], 'About 5 years for a degree; ND/HND routes exist at polytechnics.', true),
  ('architecture', 'Architecture', 'engineering', 'Designing buildings and spaces that are safe, useful and beautiful.', 'Architecture combines art, science and technology. Architects design homes, schools, hospitals and cities, thinking about how people will use each space and how it can be built safely.', array['Architectural design studio', 'Building technology and materials', 'History of architecture', 'Drawing and 3D modelling', 'Urban design']::text[], array['Mathematics', 'Physics', 'Technical Drawing', 'Fine Arts', 'Geography', 'English Language']::text[], array['Architecture firms', 'Construction companies', 'Property developers', 'Government planning offices', 'Self-employment']::text[], array['Drawing and design', 'Creativity with practical limits', 'Presenting ideas', '3D design software']::text[], array['Professional practice and registration with the Architects Registration Council of Nigeria (ARCON)', 'Master’s in Architecture (often required for professional practice)']::text[], array['build', 'creative', 'logic']::text[], array['university', 'polytechnic']::text[], 'Often a first degree plus a master’s for professional practice.', true),
  ('estate-management', 'Estate Management', 'engineering', 'Valuing, managing, buying and selling land and buildings.', 'Estate Management teaches how property works as an investment and a resource. Estate surveyors value land and buildings, manage property and advise investors and governments.', array['Property valuation', 'Land law', 'Property management', 'Real estate finance', 'Urban economics']::text[], array['Mathematics', 'Economics', 'Geography', 'English Language']::text[], array['Estate surveying firms', 'Banks and mortgage institutions', 'Property developers', 'Government land offices']::text[], array['Negotiation', 'Working with numbers', 'Report writing', 'Inspecting buildings']::text[], array['Registration with the Estate Surveyors and Valuers Registration Board of Nigeria (ESVARBON)']::text[], array['organise', 'build', 'people']::text[], array['university', 'polytechnic']::text[], 'About 5 years for a degree; ND/HND routes exist at polytechnics.', true),
  ('accounting', 'Accounting', 'business', 'Recording, checking and explaining money matters for businesses and governments.', 'Accounting teaches how organisations track their money, prepare financial reports, pay taxes and stay honest. Every business, school, church, mosque and government agency needs accountants.', array['Financial accounting', 'Cost and management accounting', 'Auditing', 'Taxation', 'Business law', 'Accounting software']::text[], array['Mathematics', 'Financial Accounting', 'Economics', 'Commerce', 'English Language']::text[], array['Accounting and audit firms', 'Banks', 'Companies of all sizes', 'Government ministries', 'NGOs']::text[], array['Accuracy with numbers', 'Honesty and integrity', 'Spreadsheets', 'Report writing']::text[], array['Professional qualifications such as ICAN or ANAN', 'Master’s in Accounting or Finance']::text[], array['organise', 'logic']::text[], array['university', 'polytechnic']::text[], 'About 4 years for a degree; ND/HND routes exist at polytechnics.', true),
  ('economics', 'Economics', 'business', 'How people, businesses and governments make choices about money and resources.', 'Economics explains prices, jobs, inflation, trade and government budgets. Economists use data and reasoning to understand what is happening and to suggest better policies.', array['Microeconomics and macroeconomics', 'Development economics', 'Statistics and econometrics', 'Public finance', 'International trade']::text[], array['Mathematics', 'Economics', 'English Language', 'Government', 'Geography']::text[], array['Central and commercial banks', 'Ministries and planning agencies', 'Research and policy organisations', 'International organisations', 'Businesses']::text[], array['Analytical thinking', 'Working with data', 'Clear writing', 'Debating ideas']::text[], array['M.Sc. in Economics', 'Professional finance or data qualifications']::text[], array['logic', 'organise', 'people']::text[], array['university']::text[], 'About 4 years for a degree.', true),
  ('business-administration', 'Business Administration', 'business', 'How to plan, organise and lead businesses and other organisations.', 'Business Administration gives a broad understanding of how organisations work — marketing, people management, finance and strategy. It suits students who want to run or manage a business.', array['Principles of management', 'Marketing', 'Human resource management', 'Business finance', 'Entrepreneurship', 'Business communication']::text[], array['Mathematics', 'Economics', 'Commerce', 'English Language', 'Government']::text[], array['Companies of all sizes', 'Own business', 'Banks', 'Public service', 'NGOs']::text[], array['Leadership', 'Organising people and tasks', 'Communication', 'Decision making']::text[], array['MBA or other management degrees', 'Professional certifications in management, marketing or HR']::text[], array['organise', 'people', 'communicate']::text[], array['university', 'polytechnic']::text[], 'About 4 years for a degree; ND/HND routes exist at polytechnics.', true),
  ('banking-finance', 'Banking and Finance', 'business', 'How banks, investments and financial markets work.', 'Banking and Finance focuses on how money moves through banks, markets and businesses — lending, saving, investing and managing risk.', array['Principles of banking', 'Corporate finance', 'Investment analysis', 'Financial markets', 'Risk management']::text[], array['Mathematics', 'Economics', 'Financial Accounting', 'Commerce', 'English Language']::text[], array['Commercial and microfinance banks', 'Fintech companies', 'Insurance and investment firms', 'Regulators']::text[], array['Working with numbers', 'Customer service', 'Analysing risk', 'Integrity']::text[], array['Professional banking qualifications', 'Investment and finance certifications', 'Master’s in Finance']::text[], array['organise', 'logic', 'people']::text[], array['university', 'polytechnic']::text[], 'About 4 years for a degree; ND/HND routes exist at polytechnics.', true),
  ('law', 'Law', 'law-society', 'Understanding the rules that govern society and how to apply them fairly.', 'Law teaches how laws are made, interpreted and enforced. Law graduates in Nigeria attend the Nigerian Law School before being called to the Bar to practise as lawyers.', array['Constitutional law', 'Criminal law', 'Contract law', 'Land law', 'Human rights', 'Legal research and writing']::text[], array['English Language', 'Literature in English', 'Government', 'History', 'Mathematics', 'Christian Religious Studies / Islamic Studies']::text[], array['Law firms', 'Courts', 'Company legal departments', 'Government ministries', 'Human rights organisations']::text[], array['Careful reading', 'Persuasive writing and speaking', 'Logical argument', 'Ethics']::text[], array['Nigerian Law School and Call to the Bar', 'LL.M. (master’s in law) to specialise']::text[], array['communicate', 'people', 'logic']::text[], array['university']::text[], 'About 5 years for a degree, then Law School.', true),
  ('political-science', 'Political Science', 'law-society', 'How governments, elections and public policies work — locally and around the world.', 'Political Science studies power, government and public decision making. It prepares students for careers in public service, policy, international relations and civil society.', array['Nigerian government and politics', 'Public administration', 'International relations', 'Political theory', 'Research methods']::text[], array['Government', 'English Language', 'History', 'Economics', 'Literature in English']::text[], array['Public service', 'Embassies and international organisations', 'NGOs and civil society', 'Media', 'Research organisations']::text[], array['Debate', 'Writing reports', 'Research', 'Understanding different views']::text[], array['Master’s in Political Science, International Relations or Public Policy']::text[], array['people', 'communicate', 'organise']::text[], array['university']::text[], 'About 4 years for a degree.', true),
  ('psychology', 'Psychology', 'education-care', 'Understanding how people think, feel, learn and behave.', 'Psychology is the scientific study of the mind and behaviour. Psychologists help people with learning, mental health, relationships and work.', array['Developmental psychology', 'Social psychology', 'Biological basis of behaviour', 'Research and statistics', 'Counselling basics']::text[], array['English Language', 'Biology', 'Mathematics', 'Economics', 'Government']::text[], array['Hospitals and clinics', 'Schools', 'Human resource departments', 'NGOs', 'Research']::text[], array['Listening', 'Empathy', 'Research', 'Confidentiality']::text[], array['Postgraduate training for clinical or counselling practice', 'Registration requirements for practising psychologists should be checked']::text[], array['people', 'life', 'communicate']::text[], array['university']::text[], 'About 4 years for a degree.', true),
  ('sociology', 'Sociology', 'law-society', 'How families, communities and societies are organised and how they change.', 'Sociology studies groups of people — families, religions, cities, workplaces — and issues such as poverty, migration and inequality. It is useful for social work, research and public service.', array['Social theory', 'Research methods', 'Population studies', 'Social problems and policy', 'Gender and development']::text[], array['English Language', 'Government', 'Economics', 'Geography', 'Mathematics']::text[], array['NGOs and development organisations', 'Social welfare departments', 'Research organisations', 'Human resource departments']::text[], array['Research', 'Understanding communities', 'Writing reports']::text[], array['Master’s in Sociology, Social Work or Development Studies']::text[], array['people', 'communicate']::text[], array['university']::text[], 'About 4 years for a degree.', true),
  ('mass-communication', 'Mass Communication', 'media', 'Journalism, broadcasting, public relations and digital media.', 'Mass Communication teaches how to gather, write and share information with large audiences through newspapers, radio, TV and the internet.', array['News writing and reporting', 'Broadcasting', 'Public relations', 'Advertising', 'Digital and social media', 'Media law and ethics']::text[], array['English Language', 'Literature in English', 'Government', 'Economics', 'Mathematics']::text[], array['TV and radio stations', 'Newspapers and online media', 'Public relations and advertising agencies', 'Company communication departments']::text[], array['Writing', 'Interviewing', 'Public speaking', 'Video and audio editing']::text[], array['Master’s in Mass Communication or Journalism', 'Professional PR and advertising qualifications']::text[], array['communicate', 'creative', 'people']::text[], array['university', 'polytechnic']::text[], 'About 4 years for a degree; ND/HND routes exist at polytechnics.', true),
  ('english-literary', 'English and Literary Studies', 'media', 'The English language, literature and the art of writing.', 'English and Literary Studies develops your reading, writing and thinking. You study African and world literature and learn how language works.', array['African and world literature', 'Linguistics', 'Creative writing', 'Literary criticism', 'Oral literature']::text[], array['English Language', 'Literature in English', 'History', 'Government', 'Christian Religious Studies / Islamic Studies']::text[], array['Publishing houses', 'Media organisations', 'Schools and universities', 'Communication departments']::text[], array['Excellent writing', 'Critical reading', 'Editing', 'Storytelling']::text[], array['Postgraduate study in literature or linguistics', 'Teaching qualifications']::text[], array['communicate', 'creative']::text[], array['university', 'college_of_education']::text[], 'About 4 years for a degree.', true),
  ('theatre-arts', 'Theatre and Film Arts', 'creative', 'Acting, directing, script writing and producing for stage and screen.', 'Theatre Arts (sometimes called Theatre and Film Studies or Performing Arts) teaches the craft and business of performance. Nigeria’s film and music industries create opportunities for skilled creatives.', array['Acting and voice', 'Directing', 'Script writing', 'Film production', 'Costume and stage design', 'Theatre history']::text[], array['English Language', 'Literature in English', 'Music', 'Fine Arts', 'Government']::text[], array['Film and TV production companies', 'Theatres', 'Broadcasting', 'Event companies', 'Self-employment']::text[], array['Performance', 'Creativity', 'Teamwork', 'Confidence']::text[], array['Master’s in Theatre or Film', 'Short professional film courses']::text[], array['creative', 'communicate', 'people']::text[], array['university', 'college_of_education']::text[], 'About 4 years for a degree.', true),
  ('agriculture', 'Agriculture', 'agriculture', 'Growing crops, raising animals and running farms using science and business.', 'Agriculture combines biology, chemistry and business to produce food and raw materials. Modern agriculture uses technology to improve yields and protect the environment.', array['Crop science', 'Animal science', 'Soil science', 'Agricultural economics', 'Farm machinery', 'Agricultural extension']::text[], array['Agricultural Science', 'Biology', 'Chemistry', 'Mathematics', 'Physics', 'English Language']::text[], array['Commercial farms', 'Agribusiness companies', 'Research institutes', 'Ministries of Agriculture', 'Own farming business']::text[], array['Practical field work', 'Planning seasons', 'Business management', 'Problem solving']::text[], array['Postgraduate study in crop, animal or soil science', 'Agribusiness training']::text[], array['nature', 'life', 'practical']::text[], array['university', 'polytechnic', 'college_of_education']::text[], 'About 5 years for a degree; ND/HND routes exist at polytechnics and colleges of agriculture.', true),
  ('food-science', 'Food Science and Technology', 'agriculture', 'Turning farm produce into safe, nutritious and lasting food products.', 'Food Science and Technology studies how food is processed, preserved, packaged and kept safe. It links farming to the food we buy.', array['Food chemistry', 'Food microbiology', 'Food processing and preservation', 'Nutrition', 'Quality control']::text[], array['Chemistry', 'Biology', 'Mathematics', 'Physics', 'Agricultural Science', 'English Language']::text[], array['Food and drink manufacturers', 'Food safety regulators', 'Research institutes', 'Own food business']::text[], array['Laboratory work', 'Attention to hygiene', 'Product development']::text[], array['Postgraduate study in food science or nutrition', 'Food safety certifications']::text[], array['nature', 'life', 'practical']::text[], array['university', 'polytechnic']::text[], 'About 5 years for a degree; ND/HND routes exist at polytechnics.', true),
  ('education', 'Education (Subject Teaching)', 'education-care', 'Training to teach a subject such as Mathematics, English, Biology or Economics.', 'Education degrees combine a teaching subject with training in how people learn. Programmes are usually named after the subject, such as “Education and Mathematics”. Colleges of education offer the NCE as another route into teaching.', array['Your chosen teaching subject', 'How children learn', 'Lesson planning', 'Classroom management', 'Teaching practice in schools', 'Guidance and counselling basics']::text[], array['English Language', 'Mathematics', 'Your intended teaching subject']::text[], array['Primary and secondary schools', 'Education ministries', 'Training organisations', 'Educational publishing']::text[], array['Explaining ideas clearly', 'Patience', 'Planning', 'Leadership']::text[], array['Registration with the Teachers Registration Council of Nigeria (TRCN)', 'Master’s in Education or Guidance and Counselling']::text[], array['people', 'communicate']::text[], array['university', 'college_of_education']::text[], 'About 4 years for a degree; NCE programmes are usually about 3 years.', true),
  ('fine-applied-arts', 'Fine and Applied Arts', 'creative', 'Painting, sculpture, graphic design, textiles and other visual arts.', 'Fine and Applied Arts develops your talent in visual art and design. Students often specialise in areas such as painting, sculpture, ceramics, textiles or graphic design.', array['Drawing and painting', 'Graphic design', 'Sculpture and ceramics', 'Textile design', 'Art history', 'Digital design tools']::text[], array['Fine Arts', 'English Language', 'Literature in English', 'Mathematics', 'Technical Drawing']::text[], array['Design studios and advertising agencies', 'Galleries', 'Publishing and media', 'Self-employment']::text[], array['Drawing', 'Creativity', 'Design software', 'Building a portfolio']::text[], array['Master of Fine Arts', 'Short courses in digital design and animation']::text[], array['creative', 'build']::text[], array['university', 'polytechnic', 'college_of_education']::text[], 'About 4 years for a degree; ND/HND routes exist at polytechnics.', true),
  ('fashion-design', 'Fashion Design and Clothing Technology', 'creative', 'Designing, making and selling clothes and accessories.', 'Fashion Design and Clothing Technology teaches how to design garments, choose fabrics, cut patterns, sew and run a fashion business. It is offered at many polytechnics.', array['Fashion illustration', 'Pattern making', 'Garment construction', 'Textile science', 'Fashion business and marketing']::text[], array['Fine Arts', 'Garment Making', 'Home Economics', 'English Language', 'Mathematics']::text[], array['Fashion houses', 'Clothing manufacturers', 'Costume departments in film and TV', 'Own fashion business']::text[], array['Sewing', 'Creativity', 'Measuring accurately', 'Business skills']::text[], array['HND or degree programmes in fashion and textiles', 'Short courses and apprenticeships with designers']::text[], array['creative', 'practical', 'organise']::text[], array['polytechnic', 'university', 'technical_college']::text[], 'ND and HND are each usually about 2 years.', true),
  ('science-lab-technology', 'Science Laboratory Technology', 'technical', 'Running laboratories and carrying out scientific tests in industry, schools and research.', 'Science Laboratory Technology (SLT) is a practical polytechnic programme. Students learn to prepare, run and maintain laboratory tests in areas such as chemistry, biology, microbiology and physics.', array['Laboratory techniques', 'Analytical chemistry', 'Microbiology techniques', 'Instrument maintenance', 'Laboratory safety']::text[], array['Chemistry', 'Biology', 'Physics', 'Mathematics', 'English Language']::text[], array['School and university laboratories', 'Industrial quality-control labs', 'Research institutes', 'Water and environmental labs']::text[], array['Precision', 'Following procedures', 'Using equipment safely', 'Record keeping']::text[], array['HND after ND', 'Degree programmes through direct entry routes']::text[], array['practical', 'life', 'logic']::text[], array['polytechnic']::text[], 'ND and HND are each usually about 2 years, often with an industrial training period.', true),
  ('electrical-installation', 'Electrical Installation and Maintenance Work', 'technical', 'Installing, testing and repairing electrical wiring and equipment.', 'This trade programme is commonly offered at technical colleges. It teaches safe electrical wiring for homes and businesses, maintenance of equipment and, increasingly, solar installation.', array['Domestic and industrial wiring', 'Electrical safety', 'Reading technical drawings', 'Testing and fault finding', 'Solar system installation basics']::text[], array['Mathematics', 'Physics', 'Basic Technology', 'Technical Drawing', 'English Language']::text[], array['Electrical contractors', 'Construction sites', 'Solar energy companies', 'Factories and facilities', 'Self-employment']::text[], array['Working safely', 'Using tools', 'Problem solving', 'Customer service']::text[], array['Trade certificates from bodies such as NABTEB', 'Polytechnic ND in Electrical Engineering', 'Apprenticeships']::text[], array['practical', 'build', 'tech']::text[], array['technical_college', 'polytechnic']::text[], 'Technical college programmes are usually about 3 years after junior secondary school.', true)
insert into public.careers (id, title, category_id, summary, responsibilities, interests, skills, work_environments, start_now, alternative_routes, licensing, published) values
  ('software-developer', 'Software Developer', 'technology', 'Writes the code behind apps, websites and computer systems.', array['Turn ideas into working software', 'Write, test and fix code', 'Work with designers and users', 'Keep systems secure and up to date']::text[], array['tech', 'logic', 'build']::text[], array['Programming', 'Problem solving', 'Teamwork', 'Patience when debugging']::text[], array['Offices and tech hubs', 'Remote work from home', 'Banks and fintech companies', 'Start-ups']::text[], array['Try free beginner coding lessons (for example HTML, Python or Scratch)', 'Join or start a coding club', 'Build a small project, such as a quiz or a calculator', 'Practise Mathematics regularly']::text[], 'Many developers study Computer Science or Software Engineering, but others come from mathematics, physics or engineering, polytechnic ND/HND programmes, or recognised coding programmes with a strong portfolio.', 'No licence is usually required to work as a developer. Professional registration with the Computer Professionals Registration Council of Nigeria (CPN) is available and may be required for some roles.', true),
  ('data-analyst', 'Data Analyst', 'technology', 'Uses data to find patterns and answer questions for organisations.', array['Collect and clean data', 'Build charts and dashboards', 'Explain what the numbers mean', 'Help leaders make decisions']::text[], array['logic', 'tech', 'organise']::text[], array['Spreadsheets', 'Statistics', 'Clear communication', 'Curiosity']::text[], array['Banks and telecom companies', 'Health programmes and NGOs', 'Government agencies', 'Remote work']::text[], array['Learn to use a spreadsheet to make simple charts', 'Collect data from a class survey and present it', 'Pay attention in Mathematics and Statistics topics']::text[], 'Data analysts come from Statistics, Economics, Computer Science, Mathematics, Engineering and many other courses. Short professional courses can add specialist skills.', 'There is no general licence for data analysts.', true),
  ('cybersecurity-analyst', 'Cybersecurity Analyst', 'technology', 'Protects computers, networks and people’s information from attacks.', array['Monitor systems for threats', 'Investigate security problems', 'Teach staff about safe online behaviour', 'Recommend ways to protect data']::text[], array['tech', 'logic']::text[], array['Networking', 'Attention to detail', 'Ethics and honesty', 'Problem solving']::text[], array['Banks and fintech companies', 'Telecom companies', 'Government and security agencies', 'Security consultancies']::text[], array['Learn how to keep your own accounts safe (strong passwords, two-step login)', 'Explore beginner networking lessons', 'Join a computer or robotics club']::text[], 'Common routes include Computer Science, Software Engineering, Cyber Security degrees, or IT support roles followed by security certifications.', 'Industry certifications are common. Registration with CPN may be relevant for some roles.', true),
  ('statistician', 'Statistician', 'technology', 'Designs surveys and analyses numbers to help people understand the world.', array['Plan surveys and experiments', 'Analyse data with statistical software', 'Check that conclusions are reliable', 'Write reports']::text[], array['logic', 'organise', 'tech']::text[], array['Mathematics', 'Statistical software', 'Report writing', 'Accuracy']::text[], array['Statistics offices', 'Research institutes', 'Banks and insurance companies', 'Health organisations']::text[], array['Practise Mathematics, especially statistics topics', 'Try analysing simple data such as football scores or weather']::text[], 'Statistics, Mathematics, Economics and Actuarial Science can all lead here.', 'There is no general licence for statisticians in Nigeria; professional associations exist.', true),
  ('medical-doctor', 'Medical Doctor', 'health', 'Diagnoses illnesses and treats patients, often specialising in one area of medicine.', array['Examine and listen to patients', 'Diagnose illnesses', 'Prescribe treatment and perform procedures', 'Educate patients and families']::text[], array['life', 'people', 'logic']::text[], array['Scientific knowledge', 'Communication and empathy', 'Decision making under pressure', 'Long-term commitment to study']::text[], array['Hospitals and clinics', 'Primary health care centres', 'Research and public health organisations']::text[], array['Work hard in Biology, Chemistry and Physics', 'Volunteer at health outreaches if allowed', 'Learn basic first aid', 'Talk to a doctor about their work']::text[], 'If you love health but medicine is not right for you, explore Nursing, Pharmacy, Medical Laboratory Science, Physiotherapy, Radiography or Public Health.', 'Doctors must complete housemanship (internship) and register with the Medical and Dental Council of Nigeria (MDCN) to practise.', true),
  ('nurse', 'Nurse', 'health', 'Cares for patients, gives treatment and supports families through illness and recovery.', array['Monitor patients’ health', 'Give medicines and treatments', 'Educate patients about health', 'Work closely with doctors and other health workers']::text[], array['life', 'people', 'practical']::text[], array['Compassion', 'Attention to detail', 'Teamwork', 'Staying calm']::text[], array['Hospitals', 'Clinics and primary health care centres', 'Schools and companies', 'Community health programmes']::text[], array['Work hard in Biology and Chemistry', 'Learn first aid', 'Practise caring responsibly for younger children or elderly relatives']::text[], 'Nursing degrees at universities and recognised schools of nursing and midwifery are both routes into nursing.', 'Nurses and midwives must be registered with the Nursing and Midwifery Council of Nigeria (NMCN).', true),
  ('pharmacist', 'Pharmacist', 'health', 'Prepares and supplies medicines and advises people on how to use them safely.', array['Check and dispense prescriptions', 'Advise patients about medicines', 'Watch for harmful drug combinations', 'Help make and test medicines']::text[], array['life', 'logic', 'people']::text[], array['Accuracy', 'Chemistry knowledge', 'Clear advice', 'Integrity']::text[], array['Community pharmacies', 'Hospitals', 'Pharmaceutical companies', 'Regulatory agencies']::text[], array['Focus on Chemistry and Biology', 'Learn how to read medicine labels carefully']::text[], 'Pharmacy technicians train through separate programmes. Related careers include pharmacology research and drug regulation.', 'Pharmacists must complete an internship and register with the Pharmacy Council of Nigeria (PCN).', true),
  ('medical-lab-scientist', 'Medical Laboratory Scientist', 'health', 'Tests samples in the laboratory to help doctors diagnose and treat patients.', array['Test blood and other samples', 'Operate laboratory equipment', 'Ensure results are accurate', 'Follow strict safety rules']::text[], array['life', 'practical', 'logic']::text[], array['Precision', 'Laboratory techniques', 'Record keeping']::text[], array['Hospital laboratories', 'Diagnostic centres', 'Public health laboratories', 'Blood banks']::text[], array['Enjoy practical work in Biology and Chemistry', 'Practise careful note taking during experiments']::text[], 'Science Laboratory Technology (polytechnic) leads to related laboratory roles.', 'Medical laboratory scientists must be registered with the Medical Laboratory Science Council of Nigeria (MLSCN).', true),
  ('microbiologist', 'Microbiologist', 'health', 'Studies bacteria, viruses and fungi to protect health and improve food and industry.', array['Grow and identify microorganisms', 'Test food, water and medicines for safety', 'Carry out research', 'Write reports']::text[], array['life', 'logic', 'nature']::text[], array['Laboratory work', 'Patience', 'Scientific writing']::text[], array['Laboratories', 'Food and drink companies', 'Hospitals', 'Research institutes']::text[], array['Pay attention to Biology practicals', 'Read about how vaccines and fermentation work']::text[], 'Microbiology, Biochemistry, Science Laboratory Technology and Food Science can all lead here.', 'Requirements depend on the workplace; some clinical roles need professional registration.', true),
  ('civil-engineer', 'Civil Engineer', 'engineering', 'Designs and supervises the building of roads, bridges, buildings and water systems.', array['Design structures and calculate loads', 'Supervise construction sites', 'Check safety and quality', 'Manage budgets and teams']::text[], array['build', 'logic', 'practical']::text[], array['Mathematics', 'Design software', 'Leadership on site', 'Safety awareness']::text[], array['Construction sites', 'Engineering offices', 'Government ministries']::text[], array['Work hard in Mathematics and Physics', 'Try Technical Drawing', 'Build models from cardboard or other materials']::text[], 'Polytechnic ND/HND in Civil Engineering Technology leads to technologist roles. Building Technology and Quantity Surveying are related.', 'Engineers and engineering technologists register with the Council for the Regulation of Engineering in Nigeria (COREN).', true),
  ('electrical-engineer', 'Electrical Engineer', 'engineering', 'Designs and maintains power systems, electronics and communication networks.', array['Design electrical systems', 'Test and maintain equipment', 'Plan solar and power projects', 'Solve electrical faults']::text[], array['build', 'logic', 'tech']::text[], array['Mathematics', 'Physics', 'Safety', 'Problem solving']::text[], array['Power companies', 'Telecom companies', 'Factories', 'Renewable energy companies']::text[], array['Focus on Physics and Mathematics', 'Build simple circuits with a safe kit and adult supervision']::text[], 'Polytechnic programmes and technical college trades such as Electrical Installation lead to related technical roles.', 'Registration with COREN is required for professional engineering practice.', true),
  ('mechanical-engineer', 'Mechanical Engineer', 'engineering', 'Designs and maintains machines, engines and manufacturing systems.', array['Design machines and parts', 'Maintain equipment', 'Improve production processes', 'Test new designs']::text[], array['build', 'logic', 'practical']::text[], array['Mathematics', 'Hands-on skills', 'Design software', 'Teamwork']::text[], array['Factories', 'Oil and gas facilities', 'Workshops', 'Engineering offices']::text[], array['Take apart and rebuild simple objects (safely)', 'Practise Physics and Technical Drawing']::text[], 'Mechanical Engineering Technology at polytechnics, and automobile or welding trades, lead to related roles.', 'Registration with COREN is required for professional engineering practice.', true),
  ('architect', 'Architect', 'engineering', 'Designs buildings and spaces that are safe, useful and beautiful.', array['Meet clients to understand their needs', 'Draw plans and 3D models', 'Work with engineers and builders', 'Check that buildings follow regulations']::text[], array['build', 'creative', 'logic']::text[], array['Drawing and design', 'Mathematics', 'Presentation', 'Design software']::text[], array['Architecture studios', 'Construction sites', 'Government planning offices']::text[], array['Sketch buildings around you', 'Try Technical Drawing and Fine Arts', 'Explore free 3D design tools']::text[], 'Related careers include urban and regional planning, interior design and building technology.', 'Architects must register with the Architects Registration Council of Nigeria (ARCON) to practise.', true),
  ('estate-surveyor', 'Estate Surveyor and Valuer', 'engineering', 'Values, manages and advises on land and buildings.', array['Inspect and value property', 'Manage rented properties', 'Advise buyers and investors', 'Write valuation reports']::text[], array['organise', 'build', 'people']::text[], array['Negotiation', 'Mathematics', 'Report writing', 'Understanding property law']::text[], array['Estate firms', 'Banks', 'Property developers', 'Government land offices']::text[], array['Learn about how rent and property prices work in your area', 'Practise Economics and Mathematics']::text[], 'Related careers include quantity surveying, urban planning and property development.', 'Estate surveyors and valuers register with the Estate Surveyors and Valuers Registration Board of Nigeria (ESVARBON).', true),
  ('accountant', 'Accountant', 'business', 'Keeps financial records accurate, prepares reports and helps organisations use money well.', array['Record and check transactions', 'Prepare financial statements', 'Handle tax and audits', 'Advise on budgets']::text[], array['organise', 'logic']::text[], array['Accuracy', 'Spreadsheets', 'Integrity', 'Analysis']::text[], array['Accounting firms', 'Companies', 'Government', 'NGOs']::text[], array['Keep a simple budget of your pocket money', 'Pay attention in Mathematics and Financial Accounting']::text[], 'Accounting degrees, polytechnic ND/HND, and professional exams (such as ICAN or ANAN) are all recognised routes.', 'Chartered accountants qualify through professional bodies such as the Institute of Chartered Accountants of Nigeria (ICAN) or the Association of National Accountants of Nigeria (ANAN).', true),
  ('economist', 'Economist', 'business', 'Studies how money, jobs and resources move through society and advises on policy.', array['Analyse economic data', 'Forecast trends', 'Advise governments and businesses', 'Write research reports']::text[], array['logic', 'organise', 'people']::text[], array['Data analysis', 'Clear writing', 'Critical thinking']::text[], array['Banks', 'Government ministries', 'Research institutes', 'International organisations']::text[], array['Follow simple news about prices and the economy', 'Practise Mathematics and Economics']::text[], 'Economics, Statistics and Mathematics degrees are common routes.', 'There is no general licence for economists.', true),
  ('banker', 'Banker / Financial Analyst', 'business', 'Helps people and businesses save, borrow, invest and manage financial risk.', array['Serve customers and businesses', 'Assess loan applications', 'Analyse investments', 'Follow financial regulations']::text[], array['organise', 'logic', 'people']::text[], array['Working with numbers', 'Customer service', 'Integrity', 'Analysis']::text[], array['Banks', 'Fintech companies', 'Investment firms', 'Insurance companies']::text[], array['Learn how savings and interest work', 'Practise Mathematics and Economics']::text[], 'Banking and Finance, Accounting, Economics and Business Administration are common routes.', 'Some finance roles require professional certifications; check with your employer or the relevant professional body.', true),
  ('business-manager', 'Entrepreneur / Business Manager', 'business', 'Starts or manages a business, organising people, money and ideas.', array['Plan products and services', 'Manage staff and money', 'Find and serve customers', 'Make decisions to grow the business']::text[], array['organise', 'people', 'communicate']::text[], array['Leadership', 'Planning', 'Communication', 'Resilience']::text[], array['Own business', 'Shops and markets', 'Offices', 'Online businesses']::text[], array['Join an entrepreneurship or business club', 'Try a small, safe project such as a school fair stall', 'Learn basic bookkeeping']::text[], 'Entrepreneurs come from every course and trade. Business Administration and Entrepreneurship courses help, but practical experience matters a lot.', 'Businesses must register with the relevant authorities; some industries need special permits.', true),
  ('lawyer', 'Lawyer', 'law-society', 'Advises clients on the law and represents them in court and negotiations.', array['Give legal advice', 'Draft contracts and documents', 'Represent clients in court', 'Research laws and past cases']::text[], array['communicate', 'people', 'logic']::text[], array['Reading and writing', 'Public speaking', 'Logical argument', 'Ethics']::text[], array['Law firms', 'Courts', 'Companies', 'Government and human rights organisations']::text[], array['Join a debate or literary club', 'Read widely, including newspapers', 'Practise writing clear arguments']::text[], 'Related careers include paralegal work, policy analysis, compliance and human rights advocacy.', 'After a law degree, graduates attend the Nigerian Law School and must be called to the Nigerian Bar to practise.', true),
  ('public-administrator', 'Public Administrator / Civil Servant', 'law-society', 'Plans and delivers government services and policies for citizens.', array['Implement government programmes', 'Write policies and reports', 'Manage public resources', 'Work with communities']::text[], array['people', 'organise', 'communicate']::text[], array['Organisation', 'Writing', 'Teamwork', 'Integrity']::text[], array['Ministries, departments and agencies', 'Local government', 'International organisations']::text[], array['Learn about how local and national government works', 'Take part in student leadership']::text[], 'Many courses lead to public service, including Political Science, Public Administration, Economics, Sociology and Law.', 'Entry is usually through recruitment processes rather than licensing.', true),
  ('psychologist', 'Psychologist', 'education-care', 'Helps people understand their thoughts, feelings and behaviour.', array['Assess and support people’s wellbeing', 'Provide counselling or therapy (with training)', 'Carry out research', 'Advise schools and organisations']::text[], array['people', 'life', 'communicate']::text[], array['Listening', 'Empathy', 'Confidentiality', 'Research']::text[], array['Hospitals', 'Schools', 'Companies', 'NGOs']::text[], array['Practise being a good listener', 'Read about how the brain and emotions work']::text[], 'Related careers include guidance counselling, social work and human resource management.', 'Clinical practice requires postgraduate training and professional registration — check current requirements.', true),
  ('social-worker', 'Social Worker', 'education-care', 'Supports vulnerable children, families and communities to get help and stay safe.', array['Assess people’s needs', 'Connect families to services', 'Protect children at risk', 'Work with communities']::text[], array['people', 'communicate']::text[], array['Empathy', 'Communication', 'Problem solving', 'Resilience']::text[], array['Social welfare departments', 'Hospitals', 'NGOs', 'Community organisations']::text[], array['Volunteer with community or religious groups', 'Learn about children’s rights']::text[], 'Social Work, Sociology and Psychology are common routes.', 'Check current professional registration requirements for social workers.', true),
  ('journalist', 'Journalist', 'media', 'Finds, checks and reports news and stories for newspapers, radio, TV and online.', array['Research and interview people', 'Write and edit stories', 'Check facts carefully', 'Present news on air or online']::text[], array['communicate', 'people', 'creative']::text[], array['Writing', 'Interviewing', 'Fact-checking', 'Curiosity']::text[], array['Newsrooms', 'Radio and TV stations', 'Online media', 'Out in the field']::text[], array['Write for your school magazine or press club', 'Practise reading the news aloud', 'Learn to check whether a story is true']::text[], 'Mass Communication, English, Political Science and many other courses can lead to journalism.', 'There is no single licence for journalists; professional unions and codes of ethics apply.', true),
  ('digital-marketer', 'Digital Marketer / Content Creator', 'media', 'Creates online content and campaigns that help organisations reach people.', array['Plan social media content', 'Write, design and edit posts and videos', 'Measure what works', 'Build online communities']::text[], array['communicate', 'creative', 'tech']::text[], array['Writing', 'Video and graphics', 'Understanding audiences', 'Analysing results']::text[], array['Marketing agencies', 'Companies', 'Media houses', 'Freelance / self-employed']::text[], array['Create safe, positive content for a school project', 'Learn basic photo and video editing', 'Study how brands tell stories']::text[], 'Mass Communication, Business Administration, Marketing and English are common routes, as are short professional courses.', 'There is no licence; advertising rules and data-privacy laws apply.', true),
  ('writer-editor', 'Writer / Editor', 'media', 'Writes and improves books, articles, scripts and other content.', array['Write original content', 'Edit for clarity and accuracy', 'Work with publishers and clients', 'Meet deadlines']::text[], array['communicate', 'creative']::text[], array['Excellent writing', 'Grammar', 'Creativity', 'Self-discipline']::text[], array['Publishing houses', 'Media and advertising', 'Freelance / self-employed']::text[], array['Keep a journal or blog (safely)', 'Read African and world literature', 'Enter school essay competitions']::text[], 'English and Literary Studies, Mass Communication, Theatre Arts and many other courses lead to writing careers.', 'No licence is needed.', true),
  ('film-theatre', 'Actor / Film and Theatre Professional', 'creative', 'Performs, directs, writes or produces for stage, film and TV.', array['Rehearse and perform', 'Write or direct productions', 'Work with crews on set', 'Promote projects']::text[], array['creative', 'communicate', 'people']::text[], array['Performance', 'Creativity', 'Teamwork', 'Resilience']::text[], array['Film sets', 'Theatres', 'Studios', 'Events']::text[], array['Join the drama club', 'Act in or film short school plays', 'Read scripts and plays']::text[], 'Theatre Arts, Mass Communication and film schools are routes; many professionals also learn through apprenticeships and experience.', 'No licence is needed; contracts and copyright knowledge are useful.', true),
  ('graphic-designer', 'Graphic Designer', 'creative', 'Creates logos, posters, adverts, websites and other visual designs.', array['Understand what a client needs', 'Create visual designs', 'Revise designs based on feedback', 'Prepare files for print or screen']::text[], array['creative', 'tech', 'build']::text[], array['Drawing', 'Design software', 'Creativity', 'Taking feedback well']::text[], array['Design studios', 'Advertising agencies', 'Media companies', 'Freelance']::text[], array['Design posters for school events', 'Learn a free design tool', 'Keep a portfolio of your work']::text[], 'Fine and Applied Arts, polytechnic design programmes and short courses all lead to design careers.', 'No licence is needed.', true),
  ('fashion-designer', 'Fashion Designer', 'creative', 'Designs and makes clothes and accessories and often runs a fashion business.', array['Sketch designs', 'Choose fabrics', 'Cut and sew garments', 'Manage customers and orders']::text[], array['creative', 'practical', 'organise']::text[], array['Sewing', 'Creativity', 'Measuring accurately', 'Business skills']::text[], array['Fashion studios', 'Clothing factories', 'Film and TV costume departments', 'Own business']::text[], array['Learn basic sewing', 'Sketch outfit ideas', 'Study local fabrics such as adire and aso-oke']::text[], 'Fashion Design at polytechnics, Fine and Applied Arts, technical college garment making, and apprenticeships with designers.', 'No licence is needed; business registration is advisable.', true),
  ('agricultural-scientist', 'Agricultural Scientist', 'agriculture', 'Improves crops, animals and farming methods using science.', array['Research better crops and livestock', 'Advise farmers', 'Test soil and plants', 'Promote sustainable farming']::text[], array['nature', 'life', 'logic']::text[], array['Biology and Chemistry', 'Field work', 'Communication with farmers']::text[], array['Research institutes', 'Farms', 'Ministries of Agriculture', 'Agribusiness companies']::text[], array['Join the Young Farmers Club', 'Grow a small garden', 'Focus on Agricultural Science and Biology']::text[], 'Agriculture, Botany, Soil Science, Animal Science and Agricultural Extension are routes.', 'Some agricultural professional bodies offer registration; check requirements for your specialism.', true),
  ('farm-entrepreneur', 'Agripreneur / Farm Manager', 'agriculture', 'Runs a farm or agribusiness that produces, processes or sells food.', array['Plan planting and harvesting', 'Manage workers and money', 'Find buyers and markets', 'Use technology to improve yields']::text[], array['nature', 'organise', 'practical']::text[], array['Planning', 'Business skills', 'Practical farming', 'Resilience']::text[], array['Farms', 'Markets', 'Food processing businesses']::text[], array['Grow vegetables at home or school', 'Learn basic bookkeeping', 'Visit a local farm']::text[], 'Agriculture, Agricultural Economics, Business Administration and practical training programmes are all routes.', 'Business registration and, for some products, food safety permits.', true),
  ('food-scientist', 'Food Scientist / Technologist', 'agriculture', 'Develops and tests food products so they are safe, nutritious and long-lasting.', array['Develop new food products', 'Test food quality and safety', 'Improve processing methods', 'Follow food safety rules']::text[], array['nature', 'life', 'practical']::text[], array['Laboratory work', 'Hygiene', 'Creativity', 'Attention to detail']::text[], array['Food factories', 'Laboratories', 'Food safety agencies']::text[], array['Cook safely and notice how food changes', 'Pay attention to Chemistry and Biology']::text[], 'Food Science and Technology, Microbiology, Biochemistry and Home Economics are routes.', 'Check professional registration requirements for food scientists and technologists.', true),
  ('teacher', 'Teacher', 'education-care', 'Helps children and young people learn and grow.', array['Plan and deliver lessons', 'Assess students’ progress', 'Support students who struggle', 'Work with parents']::text[], array['people', 'communicate']::text[], array['Explaining clearly', 'Patience', 'Organisation', 'Leadership']::text[], array['Primary and secondary schools', 'Tutorial centres', 'Online learning']::text[], array['Help classmates with topics you understand', 'Lead a study group', 'Volunteer to teach younger children']::text[], 'Education degrees, the NCE at colleges of education, or a subject degree followed by a postgraduate teaching qualification.', 'Teachers register with the Teachers Registration Council of Nigeria (TRCN).', true),
  ('school-counsellor', 'Guidance Counsellor', 'education-care', 'Supports students with learning, wellbeing and career decisions.', array['Meet students one-on-one', 'Run career guidance sessions', 'Support students’ wellbeing', 'Work with parents and teachers']::text[], array['people', 'communicate']::text[], array['Listening', 'Empathy', 'Confidentiality', 'Organisation']::text[], array['Schools', 'Universities', 'NGOs']::text[], array['Be a supportive friend', 'Take part in peer mentoring']::text[], 'Guidance and Counselling, Psychology and Education are common routes.', 'Check current professional requirements, which may include teacher registration with TRCN.', true),
  ('lab-technologist', 'Laboratory Technologist', 'technical', 'Prepares and runs scientific tests and keeps laboratories working safely.', array['Prepare samples and equipment', 'Run tests', 'Maintain instruments', 'Record results']::text[], array['practical', 'life', 'logic']::text[], array['Precision', 'Using equipment', 'Safety', 'Record keeping']::text[], array['School and university labs', 'Industrial labs', 'Research institutes']::text[], array['Volunteer to help set up school practicals', 'Learn laboratory safety rules']::text[], 'Science Laboratory Technology (ND/HND), Microbiology and Chemistry degrees.', 'Check registration requirements with the relevant professional institute for laboratory technologists.', true),
  ('electrician', 'Electrician / Solar Installer', 'technical', 'Installs and repairs electrical wiring, equipment and solar power systems.', array['Install wiring safely', 'Find and fix faults', 'Install solar panels and inverters', 'Follow safety standards']::text[], array['practical', 'build', 'tech']::text[], array['Working safely', 'Using tools', 'Problem solving', 'Customer service']::text[], array['Homes and offices', 'Construction sites', 'Factories', 'Own business']::text[], array['Pay attention in Basic Technology and Physics', 'Learn about electrical safety (never experiment with mains electricity)']::text[], 'Technical colleges, apprenticeships and polytechnic programmes. Some electricians later study engineering.', 'Trade certificates (for example through NABTEB) and any required electrical installation permits.', true)
