insert into public.admission_requirements (course_id, institution_id, admission_cycle, olevel_requirements, utme_subjects, direct_entry, notes, verification_status, source_id, last_verified_at) values
  ('computer-science', null, null, 'Five credits usually including English Language, Mathematics and Physics, plus two other science subjects.', array['Use of English', 'Mathematics', 'Physics', 'One of Biology, Chemistry, Agricultural Science, Economics or Geography']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('software-engineering', null, null, 'Five credits usually including English Language, Mathematics and Physics, plus two other science subjects.', array['Use of English', 'Mathematics', 'Physics', 'One other science subject']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('statistics', null, null, 'Five credits usually including English Language and Mathematics, plus three relevant subjects such as Physics, Chemistry or Economics.', array['Use of English', 'Mathematics', 'Two of Physics, Chemistry, Economics or Geography']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('medicine', null, null, 'Five credits usually including English Language, Mathematics, Physics, Chemistry and Biology, often at a single sitting.', array['Use of English', 'Biology', 'Chemistry', 'Physics']::text[], null, 'Medicine is highly competitive and many institutions set higher scores than other courses. Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('nursing', null, null, 'Five credits usually including English Language, Mathematics, Physics, Chemistry and Biology.', array['Use of English', 'Biology', 'Chemistry', 'Physics']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('pharmacy', null, null, 'Five credits usually including English Language, Mathematics, Physics, Chemistry and Biology.', array['Use of English', 'Biology', 'Chemistry', 'Physics']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
