  ('microbiology', null, null, 'Five credits usually including English Language, Mathematics, Biology, Chemistry and Physics.', array['Use of English', 'Biology', 'Chemistry', 'Physics or Mathematics']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
