  ('mechanical-engineering', null, null, 'Five credits usually including English Language, Mathematics, Physics and Chemistry, plus one other science or technical subject.', array['Use of English', 'Mathematics', 'Physics', 'Chemistry']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('architecture', null, null, 'Five credits usually including English Language, Mathematics and Physics, plus subjects such as Chemistry, Fine Arts, Geography or Technical Drawing.', array['Use of English', 'Mathematics', 'Physics', 'One of Chemistry, Geography, Fine Arts, Biology or Economics']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('estate-management', null, null, 'Five credits usually including English Language, Mathematics and Economics, plus two other relevant subjects.', array['Use of English', 'Mathematics', 'Economics', 'One other subject']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('accounting', null, null, 'Five credits usually including English Language, Mathematics and Economics, plus two other relevant subjects.', array['Use of English', 'Mathematics', 'Economics', 'One other social science or commercial subject']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('economics', null, null, 'Five credits usually including English Language, Mathematics and Economics, plus two other relevant subjects.', array['Use of English', 'Mathematics', 'Economics', 'One other social science subject']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('business-administration', null, null, 'Five credits usually including English Language, Mathematics and Economics, plus two other relevant subjects.', array['Use of English', 'Mathematics', 'Economics', 'One other subject']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('banking-finance', null, null, 'Five credits usually including English Language, Mathematics and Economics, plus two other relevant subjects.', array['Use of English', 'Mathematics', 'Economics', 'One other subject']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('law', null, null, 'Five credits usually including English Language and Literature in English, and at many institutions Mathematics, plus arts or social science subjects.', array['Use of English', 'Literature in English (at many institutions)', 'Two other arts or social science subjects']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('political-science', null, null, 'Five credits usually including English Language, Mathematics and Government or History.', array['Use of English', 'Government or History', 'Two other arts or social science subjects']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('psychology', null, null, 'Varies widely — some institutions place Psychology in the Social Sciences, others in the Sciences. Many ask for English Language, Mathematics and Biology.', array['Use of English', 'Varies by institution — check IBASS']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('sociology', null, null, 'Five credits usually including English Language and Mathematics, plus social science subjects.', array['Use of English', 'Three arts or social science subjects']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('mass-communication', null, null, 'Five credits usually including English Language, Literature in English and Mathematics, plus arts or social science subjects.', array['Use of English', 'Literature in English', 'Two other arts or social science subjects']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('english-literary', null, null, 'Five credits usually including English Language and Literature in English, plus other arts subjects.', array['Use of English', 'Literature in English', 'Two other arts or social science subjects']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('theatre-arts', null, null, 'Five credits usually including English Language and Literature in English, plus other arts subjects.', array['Use of English', 'Literature in English', 'Two other arts or social science subjects']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('agriculture', null, null, 'Five credits usually including English Language, Mathematics, Chemistry, Biology or Agricultural Science, and Physics.', array['Use of English', 'Chemistry', 'Biology or Agricultural Science', 'Mathematics or Physics']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('food-science', null, null, 'Five credits usually including English Language, Mathematics, Chemistry, Physics and Biology or Agricultural Science.', array['Use of English', 'Chemistry', 'Mathematics or Physics', 'Biology or Agricultural Science']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('education', null, null, 'Depends on the teaching subject. Usually five credits including English Language, Mathematics and the subject you want to teach.', array['Use of English', 'Subjects related to your teaching subject']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('fine-applied-arts', null, null, 'Five credits usually including English Language and Fine Arts, plus other relevant subjects.', array['Use of English', 'Fine Arts', 'Two other subjects']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('fashion-design', null, null, 'Requirements for ND programmes vary. Credits in English Language, Mathematics and subjects such as Fine Arts or Garment Making are common.', array['Use of English', 'Varies by polytechnic — check IBASS']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('science-lab-technology', null, null, 'Credits for ND programmes commonly include English Language, Mathematics, Chemistry and Physics or Biology.', array['Use of English', 'Chemistry', 'Biology or Physics', 'One other science subject']::text[], null, 'Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('electrical-installation', null, null, 'Technical colleges usually admit students after junior secondary school (BECE). This is not a UTME course.', '{}'::text[], null, 'Entry rules are set by each technical college and state. Polytechnic ND programmes in electrical engineering use UTME. Typical pattern seen across many institutions. Not verified for any specific institution or admission cycle — confirm on JAMB IBASS and the institution’s official website before applying.', 'unverified', null, null),
  ('computer-science', 'sample-university', '2026/2027 (sample)', 'SAMPLE: Five credits including English Language, Mathematics and Physics.', array['Use of English', 'Mathematics', 'Physics', 'Chemistry']::text[], null, 'Fictional demonstration record. It shows how an institution-specific requirement will look once verified data is added.', 'sample', null, null),
