insert into public.quiz_questions (id, prompt, helper, kind, sort_order, active) values
  ('q-logic', 'How much do you enjoy solving maths puzzles or logic problems?', 'For example: number puzzles, chess, working out the answer step by step.', 'likert', 1, true),
  ('q-life', 'How much do you enjoy learning about the human body, health or living things?', 'For example: how the heart works, why people fall sick, how plants grow.', 'likert', 2, true),
  ('q-event', 'Your class is planning an end-of-term event. Which job would you pick?', null, 'choice', 3, true),
  ('q-build', 'How much do you enjoy building, designing or improving how things work?', 'For example: making models, designing a room, figuring out how a bridge stands.', 'likert', 4, true),
  ('q-communicate', 'How much do you enjoy writing, speaking or creating content?', 'For example: essays, debates, stories, presenting, making videos.', 'likert', 5, true),
  ('q-club', 'Which school club sounds the most fun to you?', null, 'choice', 6, true),
  ('q-people', 'How much do you enjoy helping people and understanding how society works?', 'For example: helping a friend with a problem, learning about rights and government.', 'likert', 7, true),
  ('q-organise', 'How much do you enjoy organising activities or managing money?', 'For example: planning an event, keeping records, selling things, budgeting.', 'likert', 8, true),
  ('q-documentary', 'Which documentary would you most like to watch?', null, 'choice', 9, true),
  ('q-tech', 'How much do you enjoy working with computers and technology?', 'For example: using apps, coding, setting up a phone or computer for someone.', 'likert', 10, true),
  ('q-nature', 'How much do you enjoy working with plants, animals or the environment?', 'For example: gardening, caring for animals, learning about weather and climate.', 'likert', 11, true),
  ('q-broken', 'Something at home stops working. What are you most likely to do?', null, 'choice', 12, true),
  ('q-creative', 'How much do you enjoy art, fashion, music or design?', 'For example: drawing, styling outfits, making music, acting.', 'likert', 13, true),
  ('q-practical', 'How much do you enjoy practical, hands-on work with tools?', 'For example: fixing things, sewing, cooking, wiring a simple circuit.', 'likert', 14, true),
